#Requires -Version 5.1
# fix-android-definitivo.ps1
# Dos bugs combinados causaban que Android borrara la obra y no subiera:
#
# BUG 1 - Borra la obra:
#   form.obra_id se leía DESPUÉS de awaits en handleUploadFile.
#   Android re-renderiza el componente mientras espera la selección de archivos,
#   y form.obra_id se convierte en undefined antes de usarse.
#   FIX: capturar obraIdSnapshot = form.obra_id ANTES del primer await.
#
# BUG 2 - No abre galería en Android:
#   label+input con opacity:0 dentro de contenedores React en Android Chrome
#   a veces no dispara el file picker correctamente.
#   FIX: input con id="parte-file-input" en position:fixed fuera del viewport
#   (nunca tiene display:none) + label con htmlFor apuntando al id.
#   Esta es la técnica más compatible con todos los navegadores móviles.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix Android upload definitivo" -ForegroundColor Cyan

$File = Join-Path $RepoPath "src\app\partes\[id]\page.tsx"
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes($File, $bytes)

$c = [System.IO.File]::ReadAllText($File, [System.Text.Encoding]::UTF8)
$ok1 = $c.Contains("obraIdSnapshot")
$ok2 = $c.Contains('htmlFor="parte-file-input"')
$ok3 = $c.Contains('id="parte-file-input"')
$ok4 = $c.Contains('position: "fixed"')
if ($ok1) { Write-Host "  OK: obraIdSnapshot (no borra la obra)" -ForegroundColor Green } else { Write-Host "  ERROR obra" -ForegroundColor Red }
if ($ok2) { Write-Host "  OK: label htmlFor" -ForegroundColor Green } else { Write-Host "  ERROR label" -ForegroundColor Red }
if ($ok3) { Write-Host "  OK: input id fijo" -ForegroundColor Green } else { Write-Host "  ERROR input" -ForegroundColor Red }
if ($ok4) { Write-Host "  OK: input en position:fixed (fuera viewport)" -ForegroundColor Green } else { Write-Host "  ERROR position" -ForegroundColor Red }

Write-Host ""
Write-Host '  git add "src\app\partes\[id]\page.tsx"'
Write-Host '  git commit -m "fix: Android upload - snapshot obra_id + input id fijo fuera viewport"'
Write-Host '  git push'
